<script lang="ts">
  // Fonts ▸ Export Font Glyphs — one image per code point, zipped.
  //
  // The original's CDialogExport writes a bitmap per glyph through GDI, so the
  // output depends on lfQuality; here the images come from
  // backend/glyph_render.py (FreeType), which is the same pipeline and lets the
  // quality be chosen explicitly.  Everything the dialog shows — the count and
  // the preview strip — is the real output, generated by the same endpoint the
  // export uses.
  import Icon from "../icons/Icon.svelte";
  import { untrack } from "svelte";
  import { API_BASE } from "../api";
  import { t } from "../i18n.svelte";
  import { settings } from "../settings.svelte";
  import { fontStack, loadUserFonts } from "../fontStack.svelte";

  interface Props {
    show: boolean;
    onClose: () => void;
    /** Code points pre-selected by the caller (e.g. the current block). */
    initialCps?: number[];
  }
  let { show, onClose, initialCps = [] }: Props = $props();

  let range = $state("U+41-5A");
  let family = $state(settings.singleFamily || "Arial");
  let size = $state(40);
  let cellW = $state(0);
  let cellH = $state(0);
  let format = $state("png");
  let scale = $state(1);
  let fg = $state("#101010");
  let bg = $state("#ffffff");
  let families = $state<string[]>([]);
  let busy = $state(false);
  let msg = $state("");

  const FORMATS = ["png", "bmp", "gif", "jpg"];

  // ── window chrome ──
  let x = $state(160);
  let y = $state(90);
  let w = $state(0);
  let h = $state(0);
  const MAX_W = 860;
  const MAX_H = 640;

  function clampToViewport() {
    if (typeof window === "undefined") return;
    untrack(() => {
      const vw = window.innerWidth;
      const vh = window.innerHeight;
      const m = 8;
      w = Math.max(360, Math.min(MAX_W, vw - m * 2));
      h = Math.max(260, Math.min(MAX_H, vh - m * 2));
      x = Math.min(Math.max(x, m), Math.max(m, vw - w - m));
      y = Math.min(Math.max(y, m), Math.max(m, vh - h - m));
    });
  }

  let dragging = $state(false);
  let dsx = $state(0),
    dsy = $state(0),
    wsx = $state(0),
    wsy = $state(0);
  function dragStart(e: MouseEvent) {
    dragging = true;
    dsx = e.clientX;
    dsy = e.clientY;
    wsx = x;
    wsy = y;
    document.addEventListener("mousemove", dragMove);
    document.addEventListener("mouseup", dragEnd);
  }
  function dragMove(e: MouseEvent) {
    x = wsx + (e.clientX - dsx);
    y = wsy + (e.clientY - dsy);
  }
  function dragEnd() {
    dragging = false;
    document.removeEventListener("mousemove", dragMove);
    document.removeEventListener("mouseup", dragEnd);
  }

  $effect(() => {
    if (!show) return;
    clampToViewport();
    untrack(async () => {
      if (!families.length) {
        try {
          const r = await fetch(API_BASE + "/fonts");
          const d = await r.json();
          families = (d.families ?? d.fonts ?? d ?? []) as string[];
        } catch {
          families = [];
        }
      }
      if (!fontStack.userFonts.length) loadUserFonts();
      if (initialCps.length) range = toRange(initialCps);
    });
    const onResize = () => clampToViewport();
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  });

  /** Compact "U+41-5A, U+4E00" form for a code point list. */
  function toRange(cps: number[]): string {
    const sorted = [...new Set(cps)].sort((a, b) => a - b);
    const out: string[] = [];
    let i = 0;
    while (i < sorted.length) {
      let j = i;
      while (j + 1 < sorted.length && sorted[j + 1] === sorted[j] + 1) j++;
      out.push(
        j > i
          ? `U+${sorted[i].toString(16).toUpperCase()}-${sorted[j].toString(16).toUpperCase()}`
          : `U+${sorted[i].toString(16).toUpperCase()}`,
      );
      i = j + 1;
    }
    return out.join(", ");
  }

  /** Client-side mirror of the backend's range parser — for the count only. */
  function parseRangeCps(spec: string): number[] {
    const out: number[] = [];
    for (const tok of (spec || "").replace(/;/g, ",").split(",")) {
      const s = tok.trim().replace(/^U\+/i, "");
      if (!s) continue;
      const dash = s.indexOf("-");
      if (dash > 0) {
        const lo = parseInt(s.slice(0, dash), 16);
        const hi = parseInt(s.slice(dash + 1).replace(/^U\+/i, ""), 16);
        if (Number.isNaN(lo) || Number.isNaN(hi)) continue;
        for (
          let cp = Math.min(lo, hi);
          cp <= Math.max(lo, hi) && out.length < 20000;
          cp++
        )
          out.push(cp);
      } else {
        const cp = parseInt(s, 16);
        if (!Number.isNaN(cp)) out.push(cp);
      }
      if (out.length >= 20000) break;
    }
    return out;
  }

  const cps = $derived(parseRangeCps(range));
  const preview = $derived(cps.slice(0, 48));

  function previewSrc(cp: number): string {
    const p = new URLSearchParams({
      cp: String(cp),
      font: family,
      size: String(size),
      quality: String(settings.fontQuality),
      fg,
      bg,
      scale: String(scale),
    });
    if (cellW > 0 && cellH > 0) {
      p.set("cell_w", String(cellW));
      p.set("cell_h", String(cellH));
    }
    return `${API_BASE}/glyphs/preview?${p.toString()}`;
  }

  async function doExport() {
    if (!cps.length) {
      msg = "No code points";
      return;
    }
    busy = true;
    msg = "";
    try {
      const res = await fetch(API_BASE + "/glyphs/export", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          codepoints: cps,
          font: family,
          size,
          quality: settings.fontQuality,
          fg,
          bg,
          cell_w: cellW,
          cell_h: cellH,
          format,
          scale,
          name: `glyphs_${family.replace(/[^A-Za-z0-9]+/g, "_")}`,
        }),
      });
      if (!res.ok) {
        const d = await res.json().catch(() => ({}));
        throw new Error(d.error || `Export failed (${res.status})`);
      }
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `glyphs_${family.replace(/[^A-Za-z0-9]+/g, "_")}.zip`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
      msg = `${cps.length} × ${format.toUpperCase()}`;
    } catch (e) {
      msg = String((e as Error).message || e);
    }
    busy = false;
  }
</script>

{#if show}
  <div class="modal-mask" role="presentation">
    <!-- svelte-ignore a11y_no_static_element_interactions -->
    <div
      class="xgd"
      style="left:{x}px; top:{y}px; width:{w}px; height:{h}px;"
      onmousedown={(e) => e.stopPropagation()}
      role="dialog"
      aria-label={t("fonts.export_glyphs")}
      tabindex="-1"
    >
      <div
        class="xgd-head"
        onmousedown={dragStart}
        role="toolbar"
        tabindex="-1"
      >
        <span class="xgd-title">{t("fonts.export_glyphs")}</span>
        <span class="xgd-spacer"></span>
        <button class="xgd-x" onclick={onClose} title={t("dlg.close")}
          ><Icon name="close" size={14} /></button
        >
      </div>

      <div class="xgd-body">
        <label class="xgd-row wide">
          <span>{t("fonts.export_range")}</span>
          <input bind:value={range} spellcheck="false" placeholder="U+41-5A" />
        </label>
        <div class="xgd-hint">{t("fonts.export_range_hint")}</div>

        <div class="xgd-grid">
          <label class="xgd-row">
            <span>Font</span>
            <select bind:value={family}>
              {#if !families.includes(family) && !family.startsWith("u:")}
                <option value={family}>{family}</option>
              {/if}
              {#each families as f (f)}
                <option value={f}>{f}</option>
              {/each}
              {#each fontStack.userFonts as uf (uf.id)}
                <option value={"u:" + uf.id}>{uf.family} (uploaded)</option>
              {/each}
            </select>
          </label>

          <label class="xgd-row">
            <span>{t("fonts.export_size")}</span>
            <input type="number" min="6" max="512" bind:value={size} />
          </label>

          <label class="xgd-row">
            <span>{t("fonts.export_cell")}</span>
            <span class="xgd-pair">
              <input type="number" min="0" max="1024" bind:value={cellW} />
              <input type="number" min="0" max="1024" bind:value={cellH} />
            </span>
          </label>

          <label class="xgd-row">
            <span>{t("fonts.export_format")}</span>
            <select bind:value={format}>
              {#each FORMATS as f (f)}
                <option value={f}>{f.toUpperCase()}</option>
              {/each}
            </select>
          </label>

          <label class="xgd-row">
            <span>{t("fonts.export_scale")}</span>
            <select bind:value={scale}>
              <option value={1}>1×</option>
              <option value={2}>2×</option>
              <option value={3}>3×</option>
              <option value={4}>4×</option>
            </select>
          </label>

          <label class="xgd-row">
            <span>{t("fonts.export_fg")}</span>
            <input type="color" bind:value={fg} />
          </label>

          <label class="xgd-row">
            <span>{t("fonts.export_bg")}</span>
            <input type="color" bind:value={bg} />
          </label>
        </div>

        <div class="xgd-strip">
          {#each preview as cp (cp)}
            <img
              src={previewSrc(cp)}
              alt={"U+" + cp.toString(16)}
              draggable="false"
            />
          {/each}
          {#if !preview.length}<span class="xgd-hint">—</span>{/if}
        </div>
      </div>

      <div class="xgd-foot">
        <span class="xgd-count"
          >{t("fonts.export_count").replace("{n}", String(cps.length))}</span
        >
        <span class="xgd-hint"
          >quality: {[
            "default",
            "draft",
            "proof",
            "non-AA",
            "AA",
            "ClearType",
            "CT natural",
          ][settings.fontQuality]}</span
        >
        <span class="xgd-spacer"></span>
        {#if msg}<span class="xgd-msg">{msg}</span>{/if}
        <button class="xgd-go" onclick={doExport} disabled={busy}>
          {busy ? "…" : t("fonts.export_go")}
        </button>
      </div>
    </div>
  </div>
{/if}

<style>
  .modal-mask {
    position: fixed;
    inset: 0;
    z-index: 300;
    background: rgba(0, 0, 0, 0.28);
  }
  .xgd {
    position: absolute;
    box-sizing: border-box;
    min-width: 0;
    display: flex;
    flex-direction: column;
    background: var(--bg2, #fff);
    color: var(--fg);
    border: 1px solid var(--bd);
    border-radius: 10px;
    box-shadow: 0 18px 60px rgba(0, 0, 0, 0.3);
    overflow: hidden;
  }
  .xgd-head {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 7px 10px;
    background: var(--bg3, #f3f4f6);
    border-bottom: 1px solid var(--bd);
    cursor: move;
    user-select: none;
  }
  .xgd-title {
    font-size: 12px;
    font-weight: 600;
  }
  .xgd-spacer {
    flex: 1;
  }
  .xgd-x {
    border: 0;
    background: transparent;
    color: var(--fg2);
    cursor: pointer;
    padding: 3px;
    border-radius: 5px;
    display: flex;
  }
  .xgd-x:hover {
    background: var(--ac);
    color: #fff;
  }
  .xgd-body {
    flex: 1;
    min-height: 0;
    overflow: auto;
    padding: 10px 12px;
  }
  .xgd-row {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 11px;
    color: var(--fg2);
  }
  .xgd-row > span:first-child {
    width: 84px;
    flex: none;
  }
  .xgd-row.wide {
    width: 100%;
  }
  .xgd-row.wide input {
    flex: 1;
    min-width: 0;
  }
  .xgd-row input,
  .xgd-row select {
    font: inherit;
    font-size: 12px;
    padding: 4px 7px;
    border: 1px solid var(--bd);
    border-radius: 6px;
    background: var(--bg);
    color: var(--fg);
    min-width: 0;
  }
  .xgd-row input[type="number"] {
    width: 76px;
  }
  .xgd-row input[type="color"] {
    width: 30px;
    height: 24px;
    padding: 0;
    background: transparent;
  }
  .xgd-pair {
    display: flex;
    gap: 6px;
  }
  .xgd-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 8px 18px;
    margin-top: 10px;
  }
  .xgd-hint {
    font-size: 10.5px;
    color: var(--fg3);
    padding: 2px 0;
  }
  .xgd-strip {
    margin-top: 12px;
    padding: 8px;
    border: 1px solid var(--bd);
    border-radius: 8px;
    background: var(--bg3, #fafafa);
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    min-height: 56px;
    align-items: center;
  }
  .xgd-strip img {
    width: 44px;
    height: 44px;
    object-fit: contain;
    image-rendering: auto;
    border-radius: 4px;
  }
  .xgd-foot {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 8px 12px;
    border-top: 1px solid var(--bd);
    background: var(--bg3, #f3f4f6);
  }
  .xgd-count {
    font-size: 11.5px;
    font-weight: 600;
  }
  .xgd-msg {
    font-size: 11px;
    color: var(--ac);
  }
  .xgd-go {
    font: inherit;
    font-size: 12px;
    padding: 5px 14px;
    border-radius: 6px;
    border: 1px solid var(--bd);
    background: var(--ac);
    color: #fff;
    cursor: pointer;
  }
  .xgd-go:disabled {
    opacity: 0.5;
    cursor: default;
  }
</style>
